add_filter( 'woocommerce_checkout_fields', 'perfectpixel_phone_mask_field', 9999 );
add_action( 'woocommerce_after_checkout_form', 'perfectpixel_phone_mask_script' );

function perfectpixel_phone_mask_field( $fields ) {
	if ( isset( $fields['billing']['billing_phone'] ) ) {
		$fields['billing']['billing_phone']['placeholder'] = '123-456-7890';
		$fields['billing']['billing_phone']['maxlength']   = 12;
	}
	return $fields;
}

function perfectpixel_phone_mask_script() {
	?>
	<script>
	( function () {
		var groups = [ 3, 3, 4 ]; // Digits per group, joined with "-".
		var input = document.getElementById( 'billing_phone' );
		if ( ! input ) {
			return;
		}
		input.addEventListener( 'input', function () {
			var digits = input.value.replace( /\D/g, '' );
			var parts = [];
			var pos = 0;
			groups.forEach( function ( size ) {
				if ( pos < digits.length ) {
					parts.push( digits.substr( pos, size ) );
					pos += size;
				}
			} );
			input.value = parts.join( '-' );
		} );
	} )();
	</script>
	<?php
}
